style.css:
@namespace url("http://www.w3.org/1999/xhtml");
@-moz-document url-prefix("https://www.google.com"), url-prefix("https://www.youtube.com"), url-prefix("https://www.reddit.com"), url-prefix("https://www.github.com"), url-prefix("https://www.twitter.com"), url-prefix("https://www.wikipedia.org"), url-prefix("https://www.amazon.com"), url-prefix("https://www.discord.com") {
body {
    background: #181219 !important;
    color: #e9c46a !important;
    font-family: 'Cinzel', 'Garamond', serif !important;
}

a, h1, h2, h3, h4, h5, h6 {
    color: #e9c46a !important;
    text-shadow: 0 0 8px #5b3920, 0 0 2px #fff80150 !important;
}

header, footer, nav, .sidebar {
    background: linear-gradient(120deg, #302034 60%, #181219 100%) !important;
    border-top: 2px solid #e9c46a !important;
}

button, input[type="submit"], .btn {
    background: #e9c46a !important;
    color: #181219 !important;
    border: 1px solid #5b3920 !important;
    border-radius: 6px !important;
    box-shadow: 0 2px 6px #00000077 !important;
    font-family: 'Cinzel', 'Garamond', serif !important;
}

::-webkit-scrollbar {
    width: 12px;
    background: #302034;
}

::-webkit-scrollbar-thumb {
    background: #e9c46a;
    border-radius: 8px;
}
}
